using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // and DateTime.UtcNow is evaluated once at migration generation time (unchanged behavior but noted).
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 Cosmos provider now uses "$type" instead of "Discriminator".
        // For existing documents that already use "Discriminator", you must explicitly configure it:
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasPartitionKey(p => p.Category);
    }

    // BREAKING CHANGE 2: Synchronous I/O is no longer supported by the Cosmos provider in EF Core 9.
    // All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
    public async Task<List<Product>> GetProductsAsync(string category)
    {
        // Before (EF8 - now throws InvalidOperationException):
        //   return Products.Where(p => p.Category == category).ToList();
        // After (EF9 - must use async):
        return await Products.Where(p => p.Category == category).ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

